async function newchat(chatbot) {


    const bot = chatbots[chatbot];

    if (!bot) {
        throw new Error("Chatbot not found");
    }

    const jsontext = await send("newchat", {
        chatbot,
        url: bot.url
    });
    const text = jsontext;
    return text;
}

async function clickBySelector(selector) {

    return await send("clickBySelector", {
        selector
    });

}

async function imgcreator(chatbot,prompt,tabId,url){


    const bot = chatbots[chatbot];

    if (!bot) {
        throw new Error("Chatbot not found");
    }


    const jsontext = await send("imgcreator", {

        chatbot,

        write_selector: bot.inputbox,
        write_prompt: prompt,

        send_selector: bot.btnsend,

        img_selector: bot.imgbox,
        boximg_selector: bot.boximg,

        btnnosend: bot.btnnosend,


        plus_selector: bot.options.btnplus,
        options_selector: bot.options.btnoptions,
        option_selector: Number(
            bot.options.imgoptions.btnselector
        ),
        close_selector: bot.options.btnclose,


        tabid: tabId,
        url: url
    });


    return jsontext;
}

async function loginOuter(chatbot,tabId,url){
    const bot = chatbots[chatbot];
    if (!bot) throw new Error("Chatbot not found");
    const loginout = await send("loginout",{
        chatbot,

        profile_selector: bot.loginsetting.btnprofile,
        btnsprofile_selector: bot.loginsetting.btnspanel,
        btnprofile_length: bot.loginsetting.btnlength,

        tabid: tabId,
        url: url
    });
    return loginout;
}

async function loginer(chatbot, email, password, tabId, url){
    const bot = chatbots[chatbot];
    if (!bot) throw new Error("Chatbot not found");
    const loginn = await send("login",{
        chatbot,

        loginpanel_selector: bot.loginsetting.btnloginpanel,
        email_selector: bot.loginsetting.inpemail,
        pass_selector: bot.loginsetting.inppass,
        login_selector: bot.loginsetting.btnlogin,

        email,
        password,

        tabid: tabId,
        url: url
    });
    return loginn;
}

module.exports = {
    wr,
    newchat,
    onewr,
    imgcreator,
    loginOuter,
    loginer
};